// Üretilen dosya: tool/ozgun/uret.py. Kimya · Mol kavramı ve kimyasal hesaplamalar (kolay).
const ozChemistry9Kolay = <(String, String, List<String>, String)>[
  ('Avogadro sabitinin (NA) birimi aşağıdakilerden hangisidir?', 'mol⁻¹', ['g/mol', 'mol', 'L·mol⁻¹'], 'Avogadro sabiti bir mol başına düşen tanecik sayısıdır; bu nedenle birimi mol⁻¹ (1/mol) olur.'),
  ('Bir kapta 1 mol masa tenisi topu, başka bir kapta 1 mol demir bilye bulunduğu düşünülüyor. Bu iki örnek için hangisi doğrudur?', 'Tanecik sayıları eşit, kütleleri farklıdır.', ['Kütleleri eşit, tanecik sayıları farklıdır.', 'Hem kütleleri hem de tanecik sayıları birbirine eşittir.', 'Hacimleri eşit, tanecik sayıları farklıdır.'], 'Mol bir sayma birimidir; 1 mol her zaman 6,02×10²³ tanecik demektir. Taneciklerin kendi kütleleri farklı olduğundan toplam kütleler farklıdır.'),
  ('Avogadro sayısının büyüklüğünü sezmek için 6,0×10²³ saniyenin kaç yıl ettiği hesaplanıyor. Sonuç yaklaşık hangisidir? (1 yıl ≈ 3,2×10⁷ s)', '1,9×10¹⁶ yıl', ['1,9×10⁸ yıl, yani yaklaşık 190 milyon yıl', '1,9×10¹² yıl', '1,9×10²⁰ yıl'], '6,0×10²³ / 3,2×10⁷ ≈ 1,9×10¹⁶ yıl; bu, evrenin yaşının (yaklaşık 1,4×10¹⁰ yıl) milyonlarca katıdır.'),
  ('Mol kavramının atom ölçeği ile laboratuvar ölçeği arasında köprü kurmasını sağlayan temel ilişki hangisidir?', 'Bir taneciğin akb değeri, bir molünün gram değerine sayıca eşittir.', ['Bir molün kütlesi her madde için 12 gramdır.', 'Bir taneciğin kütlesi Avogadro sayısına eşittir.', 'Bir molün hacmi her madde için 22,4 litredir.'], 'Avogadro sayısı, 1 g = 6,02×10²³ akb olacak biçimde seçildiğinden örneğin bir H₂O molekülü 18 akb, bir mol su ise 18 g gelir.'),
  ('Mühendislikte kullanılan kilomol (kmol) biriminde bir kilomol maddede kaç tanecik bulunur? (NA = 6,02×10²³ mol⁻¹)', '6,02×10²⁶', ['6,02×10²⁰', '6,02×10²³', '6,02×10²⁹'], '1 kmol = 1000 mol olduğundan tanecik sayısı 1000 × 6,02×10²³ = 6,02×10²⁶ olur.'),
  ('Tek bir atomunun kütlesi 6,64×10⁻²³ g olarak ölçülen bir elementin bağıl atom kütlesi yaklaşık kaçtır? (1 akb = 1,66×10⁻²⁴ g)', '40', ['24', '56', '400'], '6,64×10⁻²³ g ÷ 1,66×10⁻²⁴ g = 40 akb; bu, kalsiyumun atom kütlesine karşılık gelir.'),
  ('Biyokimyada protein kütleleri çoğunlukla kilodalton (kDa) cinsinden verilir. Kütlesi 66 kDa olan bir proteinin mol kütlesi yaklaşık kaç g/mol\'dür?', '66 000', ['66', '6600', '6,6×10⁶'], '1 dalton = 1 akb olduğundan 66 kDa = 66 000 akb\'dir; bu da 66 000 g/mol\'lük mol kütlesine karşılık gelir.'),
  ('Ağır su (D₂O) molekülünün mol kütlesi kaç g/mol\'dür? (D = ²H = 2, O = 16)', '20', ['18', '19', '18,5'], 'D₂O\'da iki döteryum ve bir oksijen vardır: 2×2 + 16 = 20 g/mol.'),
  ('Eşit kütlelerde alınan normal su (H₂O, 18 g/mol) ve ağır su (D₂O, 20 g/mol) örneklerinde H₂O molekül sayısının D₂O molekül sayısına oranı kaçtır?', '10/9', ['9/10', '1', '100/81'], 'Eşit kütlede mol sayısı mol kütlesiyle ters orantılıdır: n(H₂O)/n(D₂O) = 20/18 = 10/9.'),
  ('Eşit kütlelerde alınan lityum (7), sodyum (23) ve potasyum (39) örnekleri için atom sayılarının doğru sıralaması hangisidir?', 'Li > Na > K', ['K > Na > Li', 'Na > Li > K', 'Li = Na = K'], 'Atom sayısı kütle/mol kütlesi ile orantılıdır; mol kütlesi en küçük olan lityumda en çok, en büyük olan potasyumda en az atom bulunur.'),
  ('Laboratuvarda karbon-13 ile zenginleştirilmiş bir karbon örneğinin ortalama atom kütlesi, doğal karbonunkine göre nasıldır?', 'Daha büyüktür.', ['Daha küçüktür.', 'Aynıdır.', 'Tam olarak 12,000 olur.'], 'Ağır izotopun bolluğu arttıkça ağırlıklı ortalama da artar; bu nedenle zenginleştirilmiş örneğin ortalama atom kütlesi 12,011\'den büyük olur.'),
  ('Kemik ve dişlerin mineral yapısında bulunan kalsiyum fosfatın, Ca₃(PO₄)₂, mol kütlesi kaç g/mol\'dür? (Ca = 40, P = 31, O = 16)', '310', ['135', '215', '278,5'], '3×40 + 2×(31 + 4×16) = 120 + 2×95 = 310 g/mol.'),
  ('Sofra şekeri olan sakkarozun, C₁₂H₂₂O₁₁, mol kütlesi kaç g/mol\'dür? (C = 12, H = 1, O = 16)', '342', ['180,5', '324', '360'], '12×12 + 22×1 + 11×16 = 144 + 22 + 176 = 342 g/mol.'),
  ('Gübre olarak kullanılan amonyum sülfatın, (NH₄)₂SO₄, mol kütlesi kaç g/mol\'dür? (N = 14, H = 1, S = 32, O = 16)', '132', ['114', '118', '150,5'], 'Parantezin dışındaki 2, NH₄ grubunun tamamını çarpar: 2×(14 + 4) + 32 + 4×16 = 36 + 32 + 64 = 132 g/mol.'),
  ('M₂CO₃ formülündeki bir karbonat tuzunun mol kütlesi 106 g/mol\'dür. M elementi hangisidir? (C = 12, O = 16; Li = 7, Na = 23, K = 39, Rb = 85)', 'Sodyum', ['Lityum', 'Potasyum', 'Rubidyum'], 'CO₃ kısmı 12 + 48 = 60 g/mol\'dür. 2M = 106 − 60 = 46 olduğundan M = 23, yani sodyumdur.'),
  ('Çamaşır sodası olarak bilinen Na₂CO₃·xH₂O hidratının mol kütlesi 286 g/mol\'dür. x kaçtır? (Na = 23, C = 12, O = 16, H = 1)', '10', ['5', '7', '12'], 'Susuz Na₂CO₃ 106 g/mol\'dür. 286 − 106 = 180 g su vardır; 180/18 = 10 olduğundan formül Na₂CO₃·10H₂O\'dur.'),
  ('Alçı taşı (jips) CaSO₄·2H₂O formülüne sahiptir. Bu mineralde kristal suyunun kütlece yüzdesi yaklaşık kaçtır? (Ca = 40, S = 32, O = 16, H = 1)', '%20,9', ['%10,47', '%26,5', '%36,0'], 'Mol kütlesi 136 + 36 = 172 g/mol\'dür. Su yüzdesi 36/172 × 100 ≈ %20,9 olur.'),
  ('2,50 g CuSO₄·xH₂O örneği sabit kütleye gelinceye kadar ısıtıldığında geriye 1,60 g susuz CuSO₄ kalıyor. x kaçtır? (CuSO₄ = 160, H₂O = 18 g/mol)', '5', ['3', '4,5', '7'], 'Susuz tuz 1,60/160 = 0,010 mol; uzaklaşan su 0,90/18 = 0,050 mol\'dür. Su/tuz mol oranı 5 olduğundan x = 5\'tir.'),
  ('Bir hidratın formülü deneysel olarak belirlenirken örnek, kütlesi değişmeyinceye kadar tekrar tekrar ısıtılıp tartılır. Bunun amacı nedir?', 'Kristal suyunun tamamen uzaklaştığından emin olmak', ['Örneğin havadaki oksijenle tamamen tepkimeye girmesini sağlamak', 'Tuzun erime noktasını belirlemek', 'Kabın kütlesini sıfırlamak'], 'Sabit kütleye kadar ısıtma, suyun tümüyle gittiğini gösterir. Su tamamen uzaklaşmazsa susuz tuz kütlesi büyük, x değeri küçük bulunur.'),
  ('CO ile N₂ moleküllerinin mol kütleleri aynıdır (28 g/mol). Bu eşitliğin bir sonucu hangisidir?', 'Eşit kütleli CO ve N₂ örneklerinde molekül sayıları eşittir.', ['İki gazın kimyasal özellikleri aynıdır.', 'Her iki molekülde atom sayıları da atom türleri de aynıdır.', 'CO ve N₂ birbirine dönüşebilir.'], 'Mol sayısı = kütle / mol kütlesi olduğundan mol kütleleri eşit maddelerin eşit kütleleri eşit sayıda tanecik içerir; kimyasal özellikler ise farklıdır.'),
  ('Genel formülü CₙH₂ₙ olan bir hidrokarbonun mol kütlesi 56 g/mol\'dür. Bu hidrokarbonun bir molekülünde kaç hidrojen atomu vardır? (C = 12, H = 1)', '8', ['4', '6', '10'], 'CₙH₂ₙ\'nin mol kütlesi 12n + 2n = 14n\'dir. 14n = 56 ise n = 4; formül C₄H₈ olup 8 hidrojen içerir.'),
  ('1 mol su (H₂O) molekülünde toplam kaç mol proton bulunur? (H için Z = 1, O için Z = 8)', '10', ['3', '8', '18,0'], 'Her H₂O molekülünde 2×1 + 8 = 10 proton vardır; bu yüzden 1 mol suda 10 mol proton bulunur.'),
  ('0,5 mol amonyum iyonunda (NH₄⁺) toplam kaç mol elektron vardır? (N için Z = 7, H için Z = 1)', '5', ['5,5', '4,5', '2,5'], 'NH₄⁺\'ta 7 + 4 = 11 proton, bir eksik yük nedeniyle 10 elektron vardır. 0,5 × 10 = 5 mol elektron.'),
  ('0,5 mol etan (C₂H₆) molekülünde toplam kaç mol kovalent bağ bulunur?', '3,5', ['3', '4', '7,0'], 'Etanda 1 C–C ve 6 C–H olmak üzere 7 bağ vardır. 0,5 × 7 = 3,5 mol bağ bulunur.'),
  ('0,3 mol etan (C₂H₆) ile aynı sayıda hidrojen atomu içeren su kaç gramdır? (H = 1, O = 16)', '16,2', ['5,4', '32,4', '10,8'], 'Etanda 0,3 × 6 = 1,8 mol H vardır. Suda molekül başına 2 H olduğundan 0,9 mol su gerekir; 0,9 × 18 = 16,2 g.'),
  ('Bir damla suyun hacmi yaklaşık 0,05 mL\'dir. Suyun yoğunluğu 1 g/mL kabul edilirse bir damlada yaklaşık kaç su molekülü bulunur? (H₂O = 18 g/mol, NA = 6,0×10²³)', '1,7×10²¹', ['3,0×10²²', '5,4×10²⁴', '2,8×10⁻³'], '0,05 g / 18 g/mol ≈ 2,8×10⁻³ mol; bu da 2,8×10⁻³ × 6,0×10²³ ≈ 1,7×10²¹ molekül eder.'),
  ('Yoğunluğu 0,8 g/mL olan saf etil alkolden (C₂H₅OH, 46 g/mol) 46 mL ölçülüyor. Bu örnek kaç moldür?', '0,8', ['1,0', '1,25', '0,46'], 'Kütle = 46 mL × 0,8 g/mL = 36,8 g. Mol sayısı = 36,8 / 46 = 0,8 mol.'),
  ('Kenar uzunluğu 2 cm olan som alüminyum küpte kaç mol alüminyum vardır? (Al = 27, yoğunluk 2,7 g/cm³)', '0,8', ['0,2', '0,4', '1,6'], 'Hacim 2³ = 8 cm³, kütle 8 × 2,7 = 21,6 g\'dır. 21,6 / 27 = 0,8 mol Al.'),
  ('Bir altın yüzükte 0,05 mol saf altın bulunmaktadır. Yüzükteki altının kütlesi kaç gramdır? (Au = 197)', '9,85', ['3,94', '19,7', '98,5'], 'Kütle = mol × mol kütlesi = 0,05 × 197 = 9,85 g.'),
  ('3,0×10²² molekülü 2,2 g gelen bir maddenin mol kütlesi kaç g/mol\'dür? (NA = 6,0×10²³)', '44', ['22', '66', '4,4'], '3,0×10²² molekül 0,05 mol\'dür. Mol kütlesi = 2,2 / 0,05 = 44 g/mol.'),
  ('Eşit mol sayılarında helyum ve metan içeren bir gaz karışımının toplam kütlesi 10 g\'dır. Karışımda kaç mol helyum vardır? (He = 4, CH₄ = 16)', '0,5', ['1,0', '2,5', '0,25'], 'Her birinden n mol varsa 4n + 16n = 20n = 10 g; n = 0,5 mol.'),
  ('Yalnızca formülü bilinen bir maddenin verilen kütlesinden içerdiği atom sayısına ulaşmak için hangi işlem sırası izlenir?', 'Kütle → mol → molekül sayısı → atom sayısı', ['Kütle → atom sayısı → mol → molekül sayısı', 'Mol → kütle → hacim → atom sayısı', 'Atom sayısı → kütle → mol → molekül sayısı'], 'Önce kütle mol kütlesine bölünerek mol bulunur, mol NA ile çarpılarak molekül sayısı, bu da molekül başına atom sayısıyla çarpılarak atom sayısı elde edilir.'),
  ('Bir bileşiği oluşturan elementlerin kütlece oranının sabit olduğunu 18. yüzyılın sonlarında deneylerle ortaya koyan Fransız kimyacı kimdir?', 'Joseph Louis Proust', ['Antoine Lavoisier', 'Claude Louis Berthollet', 'Joseph Gay-Lussac'], 'Sabit oranlar yasası Joseph Louis Proust\'a dayanır; Proust bakır karbonat gibi bileşiklerin kaynağı ne olursa olsun aynı bileşimde olduğunu göstermiştir.'),
  ('FeO ve Fe₂O₃ bileşiklerinde eşit kütlede demirle birleşen oksijen kütleleri oranı (FeO / Fe₂O₃) kaçtır?', '2/3', ['1/2', '3/2', '1/3'], 'Demir atomu başına FeO\'da 1, Fe₂O₃\'te 1,5 oksijen vardır. Oran 1 / 1,5 = 2/3\'tür.'),
  ('Bir bileşikte X/Y kütle oranı 3/5\'tir. Bu bileşikte X\'in kütlece yüzdesi kaçtır?', '%37,5', ['%60,0', '%62,5', '%30'], '3 g X ile 5 g Y birleşir; 8 g bileşikte X\'in payı 3/8 = %37,5\'tir.'),
  ('Sabit oranlar yasası şeker ile suyun oluşturduğu karışım için neden geçerli değildir?', 'Karışımın bileşenleri istenen her oranda bir araya getirilebilir.', ['Şeker ve su kimyasal tepkimeye girerek yeni bir bileşik oluşturur.', 'Su molekülünün kendi bileşimi sabit değildir.', 'Karışımlarda kütle korunmaz.'], 'Sabit oranlar yasası saf bileşikler içindir. Karışımlarda bileşenler kimyasal bağ oluşturmadığından oranları serbestçe değişebilir.'),
  ('Bir metalin 9 g\'ı 8 g oksijenle artansız birleşiyor. Metalin bileşiklerinde +3 değerlik gösterdiği biliniyorsa atom kütlesi kaçtır?', '27', ['9', '18', '24,5'], '8 g oksijenle birleşen kütle eşdeğer kütledir (9 g). Atom kütlesi = eşdeğer kütle × değerlik = 9 × 3 = 27 (alüminyum).'),
  ('Propan (C₃H₈) bileşiğinde karbonun hidrojene kütle oranı (C/H) kaçtır? (C = 12, H = 1)', '9/2', ['3/8', '8/3', '3/2'], 'C kütlesi 3×12 = 36, H kütlesi 8×1 = 8\'dir. 36/8 = 9/2.'),
  ('Kapalı bir şişede gerçekleşen kimyasal tepkimede toplam kütle değişmez. Aşağıdaki niceliklerden hangisinin tepkime sırasında korunması gerekmez?', 'Molekül sayısı', ['Atom sayısı', 'Toplam kütle', 'Element türleri'], 'Tepkimelerde atomlar yeniden düzenlenir; atom sayısı, element türleri ve kütle korunur. Molekül sayısı ise artabilir, azalabilir ya da aynı kalabilir.'),
  ('N₂(g) + 3H₂(g) → 2NH₃(g) tepkimesinde aynı sıcaklık ve basınçta 30 L hidrojen gazı tamamen harcanırsa kaç litre amonyak oluşur?', '20', ['10', '45', '60,0'], 'Gazlarda aynı koşullarda hacim oranı mol oranına eşittir: 3 hacim H₂\'den 2 hacim NH₃ oluşur; 30 × 2/3 = 20 L.'),
  ('2CO(g) + O₂(g) → 2CO₂(g) tepkimesi için aynı koşullarda 10 L CO ile 10 L O₂ karıştırılıp tam verimle tepkimeye sokuluyor. Tepkime sonunda kapta toplam kaç litre gaz bulunur?', '15', ['10', '20', '12,5'], '10 L CO, 5 L O₂ harcayıp 10 L CO₂ oluşturur; 5 L O₂ artar. Toplam gaz 10 + 5 = 15 L\'dir.'),
  ('Aynı koşullarda 20 mL H₂ ile 20 mL O₂ karıştırılıp tam verimle tepkimeye sokuluyor ve oluşan su yoğuşturuluyor. Geriye hangi gazdan kaç mL kalır?', '10 mL O₂', ['10 mL H₂', '20 mL O₂', 'Hiç gaz kalmaz, hacim sıfırlanır.'], '2H₂ + O₂ → 2H₂O\'ya göre 20 mL H₂, 10 mL O₂ harcar. Su sıvılaştığından geriye yalnızca 10 mL O₂ kalır.'),
  ('Hacimce %20 oksijen içerdiği kabul edilen hava ile aynı koşullarda 10 L metan (CH₄) tamamen yakılmak isteniyor. En az kaç litre hava gerekir?', '100', ['20', '50', '1000'], 'CH₄ + 2O₂ → CO₂ + 2H₂O; 10 L metan için 20 L O₂ gerekir. Hava %20 O₂ içerdiğinden 20 / 0,20 = 100 L hava gerekir.'),
  ('25 °C ve 1 atm (oda koşulları) için 1 mol ideal gazın hacmi yaklaşık kaç litre alınır?', '24,5', ['22,4', '11,2', '27,3'], 'Normal koşullarda (0 °C) 22,4 L olan molar hacim, sıcaklık 25 °C\'ye çıkınca yaklaşık 22,4 × 298/273 ≈ 24,5 L olur.'),
  ('Propan (C₃H₈) tamamen yandığında C₃H₈ + 5O₂ → 3CO₂ + 4H₂O tepkimesi gerçekleşir. 8,8 g propanın yanmasıyla oluşan CO₂ normal koşullarda kaç litre hacim kaplar? (C = 12, H = 1)', '13,44', ['4,48', '6,72', '26,88'], '8,8 / 44 = 0,2 mol propan; 0,2 × 3 = 0,6 mol CO₂ oluşur. 0,6 × 22,4 = 13,44 L.'),
  ('Sabit sıcaklık ve basınçta, N₂ ve H₂ gazlarının 1:3 hacim oranındaki karışımı tamamen NH₃\'e dönüşürse gaz hacmi nasıl değişir?', 'Başlangıç hacminin yarısına iner.', ['Başlangıç hacminin iki katına çıkar.', 'Değişmez, çünkü kütle korunur.', 'Başlangıç hacminin dörtte birine iner.'], '1 hacim N₂ ile 3 hacim H₂ (toplam 4 hacim) 2 hacim NH₃ verir; gaz hacmi 4\'ten 2\'ye, yani yarıya iner.'),
  ('2NH₃(g) → N₂(g) + 3H₂(g) tepkimesine göre aynı koşullarda 40 mL amonyak tamamen ayrıştırılıyor. Oluşan gazların toplam hacmi kaç mL\'dir?', '80', ['40', '60', '120'], '2 hacim NH₃\'ten 1 hacim N₂ ve 3 hacim H₂ oluşur. 40 mL NH₃\'ten 20 mL N₂ ve 60 mL H₂, toplam 80 mL gaz çıkar.'),
  ('5,6 g demir oksijenle tamamen tepkimeye girerek 8,0 g demir oksit oluşturuyor. Oksidin basit formülü hangisidir? (Fe = 56, O = 16)', 'Fe₂O₃', ['FeO', 'Fe₃O₄', 'FeO₂'], 'Fe: 5,6/56 = 0,10 mol; O: (8,0 − 5,6)/16 = 0,15 mol. Oran 0,10 : 0,15 = 2 : 3 olduğundan formül Fe₂O₃\'tür.'),
  ('Kütlece %52,9 alüminyum ve %47,1 oksijen içeren bileşiğin basit formülü hangisidir? (Al = 27, O = 16)', 'Al₂O₃', ['AlO', 'AlO₂', 'Al₃O₂'], 'Al: 52,9/27 ≈ 1,96; O: 47,1/16 ≈ 2,94. Oran yaklaşık 1 : 1,5 = 2 : 3 olduğundan formül Al₂O₃ olur.'),
  ('50 g saf kalsiyum karbonatta (CaCO₃) kaç gram kalsiyum bulunur? (Ca = 40, C = 12, O = 16)', '20', ['12', '25', '40'], 'CaCO₃\'ün mol kütlesi 100 g/mol\'dür; 50 g = 0,5 mol olup 0,5 × 40 = 20 g kalsiyum içerir.'),
  ('İçinde 4,6 g sodyum bulunan sodyum hidroksit (NaOH) kaç gramdır? (Na = 23, O = 16, H = 1)', '8', ['4', '9,2', '16'], '4,6 g Na = 0,2 mol. Her NaOH\'ta bir Na olduğundan 0,2 mol NaOH = 0,2 × 40 = 8 g.'),
  ('XO formülündeki bir oksit kütlece %60 X içermektedir. X\'in atom kütlesi kaçtır? (O = 16)', '24', ['9,6', '32', '40'], 'X / (X + 16) = 0,60 → X = 0,6X + 9,6 → 0,4X = 9,6 → X = 24 (magnezyum).'),
  ('Kahve ve çayda bulunan kafeinin formülü C₈H₁₀N₄O₂\'dir (194 g/mol). Kafeinde azotun kütlece yüzdesi yaklaşık kaçtır? (N = 14)', '%28,9', ['%14,43', '%7,2', '%49,5'], 'Bir molekülde 4 azot vardır: 4 × 14 = 56. 56/194 × 100 ≈ %28,9.'),
  ('Bir demir takviyesi tableti 304 mg demir(II) sülfat (FeSO₄, 152 g/mol) içermektedir. Tablet kaç miligram demir sağlar? (Fe = 56)', '112', ['56', '1120', '76'], '304 mg FeSO₄ = 2 mmol\'dür. Her formül biriminde bir Fe olduğundan 2 mmol × 56 = 112 mg demir.'),
  ('Aşağıdaki bileşiklerden hangisinin molekül formülü basit formülüyle aynı değildir?', 'H₂O₂', ['CH₃OH', 'CH₄', 'NH₃'], 'Hidrojen peroksitte H : O = 2 : 2 = 1 : 1 olduğundan basit formülü HO\'dur. Diğerlerinde atom oranları zaten en sade hâldedir.'),
  ('Yalnız karbon ve hidrojen içeren bir bileşik yakıldığında 0,4 mol CO₂ ve 0,5 mol H₂O oluşuyor. Bileşiğin basit formülü hangisidir?', 'C₂H₅', ['C₄H₁₀O', 'CH₂', 'C₂H₃'], 'C mol sayısı 0,4; H mol sayısı 2 × 0,5 = 1,0\'dır. C : H = 0,4 : 1,0 = 2 : 5 olduğundan basit formül C₂H₅\'tir.'),
  ('Bir organik bileşik oksijenle tamamen yakıldığında ürün olarak yalnızca CO₂ ve H₂O oluşuyor. Bileşiğin bileşimi hakkında kesin olarak ne söylenebilir?', 'C ve H kesin vardır; O için karar verilemez.', ['Yalnızca C ve H içerir.', 'C, H ve O elementlerinin üçünü de kesinlikle içerir.', 'Yalnızca C içerir; H oksijenden gelir.'], 'CO₂\'deki karbon ve H₂O\'daki hidrojen yalnızca bileşikten gelebilir. Oksijen ise hem bileşikten hem de yakıcı O₂\'den gelebileceğinden kütle hesabı yapılmadan karar verilemez.'),
  ('8,8 g CO₂ içinde kaç gram karbon bulunur? (C = 12, O = 16)', '2,4', ['1,2', '4,4', '0,24'], '8,8 g CO₂ = 0,2 mol\'dür; her molekülde bir C bulunduğundan 0,2 × 12 = 2,4 g karbon vardır.'),
  ('Tütünde bulunan nikotinin basit formülü C₅H₇N, mol kütlesi 162 g/mol\'dür. Nikotinin molekül formülü hangisidir? (C = 12, H = 1, N = 14)', 'C₁₀H₁₄N₂', ['C₅H₇N', 'C₁₅H₂₁N₃', 'C₁₀H₁₂N₂O'], 'Basit formülün kütlesi 60 + 7 + 14 = 81\'dir. 162 / 81 = 2 olduğundan molekül formülü C₁₀H₁₄N₂\'dir.'),
  ('Ostwald yönteminin ilk basamağında amonyak yakılır: NH₃ + O₂ → NO + H₂O. Denklem en küçük tam sayılarla denkleştirildiğinde O₂\'nin katsayısı kaç olur?', '5', ['3', '4', '10'], 'Denkleştirilmiş hâli 4NH₃ + 5O₂ → 4NO + 6H₂O\'dur. Sağda 4 + 6 = 10 oksijen atomu olduğundan O₂\'nin katsayısı 5\'tir.'),
  ('Hücresel solunumun genel denklemi C₆H₁₂O₆ + O₂ → CO₂ + H₂O en küçük tam sayılarla denkleştirildiğinde katsayılar toplamı kaç olur?', '19', ['13', '18', '24'], 'C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O; katsayılar toplamı 1 + 6 + 6 + 6 = 19\'dur.'),
  ('Kimyasal denklemlerde maddenin formülünden sonra yazılan "(suda)" ya da "(aq)" simgesi neyi belirtir?', 'Maddenin suda çözünmüş hâlde bulunduğunu', ['Maddenin suyla tepkimeye girdiğini', 'Maddenin kristal suyu içerdiğini', 'Tepkimenin su banyosunda ısıtılarak yürütüldüğünü'], 'Hâl simgeleri (k), (s), (g) ve (suda/aq) maddelerin fiziksel durumunu gösterir; (suda) maddenin sulu çözelti hâlinde olduğunu anlatır.'),
  ('Asidik ortamda MnO₄⁻ + 5Fe²⁺ + 8H⁺ → Mn²⁺ + 5Fe³⁺ + 4H₂O tepkimesine göre 0,02 mol KMnO₄ ile kaç mol Fe²⁺ tamamen yükseltgenir?', '0,1', ['0,02', '0,04', '0,016'], 'Denkleme göre 1 mol MnO₄⁻, 5 mol Fe²⁺\'yı yükseltger. 0,02 × 5 = 0,1 mol Fe²⁺.'),
  ('Zn + Ag⁺ → Zn²⁺ + Ag denkleminde her elementten iki tarafta eşit sayıda atom bulunduğu hâlde denklemin denk olmadığı söylenir. Bunun nedeni nedir?', 'İki taraftaki toplam yükler eşit değildir.', ['Çinkonun atom kütlesi gümüşünkinden küçüktür.', 'Gümüş iyonları çözeltide serbest bulunamaz.', 'Atom sayıları eşit olsa bile kütleler korunmamıştır, bu nedenle denk değildir.'], 'Sol tarafta +1, sağ tarafta +2 yük vardır. Denkleştirilmiş hâli Zn + 2Ag⁺ → Zn²⁺ + 2Ag\'dir; iyonik denklemlerde yük de korunmalıdır.'),
  ('2SO₂(g) + O₂(g) → 2SO₃(g) denkleminden aşağıdaki bilgilerden hangisi çıkarılamaz?', 'Tepkimenin ne kadar sürede tamamlandığı', ['2 mol SO₂\'nin 1 mol O₂ ile tepkimeye girdiği', 'Girenlerin ve ürünlerin gaz hâlinde olduğu', 'Ürünün kükürt ve oksijen atomlarından oluştuğu'], 'Denkleştirilmiş denklem maddelerin kimliğini, hâllerini ve mol oranlarını verir; tepkimenin hızı ya da süresi denklemden anlaşılamaz.'),
  ('Alüminyumun hidroklorik asitle tepkimesini doğru ve denk biçimde gösteren denklem hangisidir?', '2Al + 6HCl → 2AlCl₃ + 3H₂', ['Al + 3HCl → AlCl₃ + H₂', 'Al + 2HCl → AlCl₂ + H₂', '2Al + 3HCl → 2AlCl₃ + 3/2 H₂'], 'Alüminyum +3 yüklü iyon oluşturduğundan ürün AlCl₃\'tür. 2Al + 6HCl → 2AlCl₃ + 3H₂ hem atom hem de formül bakımından doğrudur.'),
  ('Amonyağın saf oksijende yanarak azot gazı ve su oluşturması NH₃ + O₂ → N₂ + H₂O ile gösterilir. En küçük tam sayılarla denkleştirildiğinde katsayılar toplamı kaçtır?', '15', ['9', '12', '17'], '4NH₃ + 3O₂ → 2N₂ + 6H₂O; toplam 4 + 3 + 2 + 6 = 15.'),
  ('Kabartma tozundaki sodyum bikarbonatın ısıyla ayrışması NaHCO₃ → Na₂CO₃ + H₂O + CO₂ denklemiyle gösterilir. En küçük tam sayılarla denkleştirildiğinde NaHCO₃\'ün katsayısı kaç olur?', '2', ['1', '3', '4'], 'Sağda 2 Na bulunduğundan sola 2NaHCO₃ yazılır: 2NaHCO₃ → Na₂CO₃ + H₂O + CO₂. Diğer atomlar da bu durumda denktir.'),
  ('Ca(OH)₂ + H₃PO₄ → Ca₃(PO₄)₂ + H₂O denklemi en küçük tam sayılarla denkleştirildiğinde suyun katsayısı kaç olur?', '6', ['2', '3', '12'], '3Ca(OH)₂ + 2H₃PO₄ → Ca₃(PO₄)₂ + 6H₂O. Ca için 3, PO₄ için 2 alınınca 6 OH⁻ ile 6 H⁺ birleşerek 6 H₂O verir.'),
  ('Doğal gazdaki hidrojen sülfürden kükürt elde edilen Claus yönteminde H₂S + SO₂ → S + H₂O tepkimesi gerçekleşir. En küçük tam sayılarla denkleştirildiğinde kükürdün katsayısı kaç olur?', '3', ['1', '2', '4'], '2H₂S + SO₂ → 3S + 2H₂O. H₂S\'deki −2 ve SO₂\'deki +4 kükürt, ikisi de 0 basamağına geçer.'),
  ('Yükseltgenme basamağı (elektron aktarımı) yöntemiyle denkleştirmenin temel ilkesi hangisidir?', 'Verilen ve alınan elektron sayıları eşitlenir.', ['Her elementin yükseltgenme basamağı sıfıra eşitlenir.', 'Ürünlerin katsayıları girenlerinkinden büyük seçilir.', 'Yalnızca oksijen ve hidrojen atomları sayılır.'], 'Yükseltgenen türün verdiği toplam elektron, indirgenen türün aldığı toplam elektrona eşit olacak biçimde katsayılar belirlenir; sonra kalan atomlar dengelenir.'),
  ('Uzay araçlarında solunan havadaki CO₂, 2LiOH + CO₂ → Li₂CO₃ + H₂O tepkimesiyle tutulur. 44 kg CO₂\'yi tutmak için en az kaç kg LiOH gerekir? (Li = 7, O = 16, H = 1, C = 12)', '48', ['24', '44', '120'], '44 kg CO₂ = 1 kmol\'dür; 2 kmol LiOH gerekir. LiOH 24 g/mol olduğundan 2 × 24 = 48 kg.'),
  ('Mayalanmada C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂ tepkimesi gerçekleşir. 360 g glukoz tamamen tepkimeye girerse en çok kaç gram etanol oluşur? (C = 12, H = 1, O = 16)', '184', ['92', '176', '1840'], '360 / 180 = 2 mol glukoz, 4 mol etanol verir. 4 × 46 = 184 g etanol oluşur.'),
  ('Fotosentezin genel denklemi 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂\'dir. Bir bitki 1,2 mol O₂ açığa çıkardığında kaç gram glukoz üretilmiş olur? (C₆H₁₂O₆ = 180 g/mol)', '36', ['18', '72', '216'], '6 mol O₂ başına 1 mol glukoz oluşur. 1,2 / 6 = 0,2 mol glukoz; 0,2 × 180 = 36 g.'),
  ('4Fe + 3O₂ → 2Fe₂O₃ tepkimesine göre 11,2 g demir tamamen paslanırsa kaç gram demir(III) oksit oluşur? (Fe = 56, O = 16)', '16', ['8', '22,4', '32'], '11,2 / 56 = 0,2 mol Fe, 0,1 mol Fe₂O₃ verir. 0,1 × 160 = 16 g.'),
  ('Yüksek fırında Fe₂O₃ + 3CO → 2Fe + 3CO₂ tepkimesi gerçekleşir. 1,6 ton saf Fe₂O₃\'ten en çok kaç ton demir elde edilebilir? (Fe = 56, O = 16)', '1,12', ['0,56', '1,60', '2,24'], 'Fe₂O₃\'ün 160 kütle biriminden 112\'si demirdir. 1,6 × 112/160 = 1,12 ton demir elde edilir.'),
  ('Gümüş eşyaların kararması 4Ag + 2H₂S + O₂ → 2Ag₂S + 2H₂O tepkimesiyle olur. 0,02 mol Ag₂S oluşması için kaç gram gümüş harcanır? (Ag = 108)', '4,32', ['2,16', '8,64', '1,08'], 'Her Ag₂S\'de 2 Ag vardır; 0,02 mol Ag₂S için 0,04 mol Ag gerekir. 0,04 × 108 = 4,32 g.'),
  ('Termit tepkimesi Fe₂O₃ + 2Al → Al₂O₃ + 2Fe\'ye göre 5,4 g alüminyum yeterli demir(III) oksitle tepkimeye girerse kaç gram demir oluşur? (Al = 27, Fe = 56)', '11,2', ['5,6', '22,4', '10,8'], '5,4 / 27 = 0,2 mol Al, eşit mol sayısında (0,2 mol) Fe verir. 0,2 × 56 = 11,2 g.'),
  ('Suyun elektrolizi 2H₂O → 2H₂ + O₂ denklemine göre gerçekleşir. 36 g su tamamen ayrıştırılırsa toplam kaç mol gaz oluşur? (H₂O = 18 g/mol)', '3', ['2', '4', '1,5'], '36 g su 2 mol\'dür; 2 mol H₂ ve 1 mol O₂, toplam 3 mol gaz oluşur.'),
  ('Gübre üretiminde NH₃ + HNO₃ → NH₄NO₃ tepkimesi kullanılır. 1,7 ton amonyak tamamen tepkimeye girerse en çok kaç ton amonyum nitrat elde edilir? (N = 14, H = 1, O = 16)', '8', ['1,7', '4', '16'], '1,7 ton NH₃ = 1,0×10⁵ mol\'dür. Aynı mol sayıda NH₄NO₃ (80 g/mol) oluşur: 1,0×10⁵ × 80 g = 8×10⁶ g = 8 ton.'),
  ('1 kg saf karbon tamamen yandığında yaklaşık 3,67 kg CO₂ oluşur. Ürün kütlesinin yakıttan büyük olması nasıl açıklanır?', 'Havadaki oksijen ürüne katılmıştır.', ['Yanma sırasında kütle yoktan var olmuştur.', 'Karbon atomları yanarken bölünerek çoğalmıştır.', 'Ölçüm hatası olup gerçekte ürün 1 kg olmalıdır.'], 'C + O₂ → CO₂\'de her 12 g karbona 32 g oksijen eklenir; 1 kg karbon 44/12 ≈ 3,67 kg CO₂ verir. Toplam kütle (karbon + oksijen) korunur.'),
  ('2A + 3B → 4C tepkimesine göre 6 mol C oluşması için kaç mol B harcanmalıdır?', '4,5', ['3', '6', '8'], 'B ile C\'nin mol oranı 3 : 4\'tür. 6 × 3/4 = 4,5 mol B gerekir.'),
  ('Denkleştirilmiş bir denklemdeki katsayılar oranı ile tepkimeye giren maddelerin kütle oranı genellikle neden aynı değildir?', 'Maddelerin mol kütleleri farklıdır.', ['Kütle tepkime sırasında korunmaz.', 'Katsayılar yalnızca gazlar için anlamlıdır.', 'Katsayılar atom sayısını değil molekül hacmini gösterir.'], 'Katsayılar mol (tanecik sayısı) oranını verir. Kütle = mol × mol kütlesi olduğundan mol kütleleri farklı maddelerde kütle oranı katsayı oranından farklı çıkar.'),
  ('Bir sandviç 2 dilim ekmek ve 1 dilim peynirle hazırlanıyor. Elde 10 dilim ekmek ve 7 dilim peynir varsa, sınırlayıcı bileşen benzetmesinde hangi malzeme sınırlayıcı bileşene karşılık gelir?', 'Ekmek', ['Peynir', 'Sandviç', 'Toplam dilim sayısı'], '10 dilim ekmek ancak 5 sandviçe yeter; bunun için 5 peynir gerekir ve 2 peynir artar. Ürün miktarını sınırlayan ekmek olduğundan sınırlayıcı bileşen benzeridir.'),
  ('N₂ + 3H₂ → 2NH₃ tepkimesi için kütleleri eşit olan 28\'er gram N₂ ve H₂ tam verimle tepkimeye sokuluyor. En çok kaç gram NH₃ oluşur? (N = 14, H = 1)', '34', ['17', '56', '158,7'], 'N₂: 1 mol, H₂: 14 mol\'dür. 1 mol N₂ yalnızca 3 mol H₂ harcar; N₂ sınırlayıcıdır ve 2 mol (34 g) NH₃ oluşur.'),
  ('CS₂ + 3O₂ → CO₂ + 2SO₂ tepkimesine göre 0,2 mol CS₂ ile 0,5 mol O₂ bir kapta bulunuyor. CS₂\'nin tamamının yanabilmesi için kaba en az kaç mol daha O₂ eklenmelidir?', '0,1', ['0,3', '0,6', '0,05'], '0,2 mol CS₂ için 0,6 mol O₂ gerekir. Kapta 0,5 mol bulunduğundan 0,1 mol daha O₂ eklenmelidir.'),
  ('Kapalı bir kapta 10 g H₂ ile 64 g O₂ su oluşturmak üzere tam verimle tepkimeye sokuluyor. Tepkime sonunda kaptaki maddelerin toplam kütlesi kaç gramdır?', '74', ['72', '64', '82'], 'Hangi madde artarsa artsın kapalı kapta toplam kütle korunur: 10 + 64 = 74 g. (72 g su oluşur, 2 g H₂ artar.)'),
  ('Normal koşullarda 4,48 L H₂ ile 4,48 L Cl₂ gazları H₂ + Cl₂ → 2HCl tepkimesine göre artansız birleşiyor. Oluşan HCl kaç gramdır? (H = 1, Cl = 35,5)', '14,6', ['7,3', '29,2', '3,65'], 'Her gazdan 4,48 / 22,4 = 0,2 mol vardır ve 1 : 1 oranında tükenirler. 0,4 mol HCl × 36,5 = 14,6 g.'),
  ('CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂ tepkimesinde 10 g CaCO₃ üzerine 0,1 mol HCl içeren asit ekleniyor. Tepkime tamamlandığında kaç gram CaCO₃ tepkimeye girmeden kalır? (Ca = 40, C = 12, O = 16)', '5', ['0', '2,5', '7,5'], '10 g CaCO₃ = 0,1 mol olup 0,2 mol HCl gerektirir. 0,1 mol HCl yalnızca 0,05 mol (5 g) CaCO₃ harcar; 5 g CaCO₃ artar.'),
  ('Kütlece %80 saflıkta CaCO₃ içeren 25 g kireç taşı ısıtıldığında CaCO₃ → CaO + CO₂ tepkimesiyle en çok kaç gram CO₂ oluşur? (Safsızlıklar ayrışmaz; Ca = 40, C = 12, O = 16)', '8,8', ['11,0', '4,4', '22,0'], 'Örnekteki CaCO₃ 25 × 0,80 = 20 g = 0,2 mol\'dür. 0,2 mol CO₂ × 44 = 8,8 g.'),
  ('Saf olmayan bir çinko örneğinin 10 g\'ı yeterli HCl ile tepkimeye girerek Zn + 2HCl → ZnCl₂ + H₂ tepkimesine göre 0,1 mol H₂ oluşturuyor. Safsızlıklar asitle tepkimeye girmiyorsa örnek kütlece yüzde kaç çinko içerir? (Zn = 65)', '65', ['35', '50', '100'], '0,1 mol H₂ için 0,1 mol Zn = 6,5 g gerekir. 6,5 / 10 × 100 = %65.'),
  ('İki basamaklı bir sentezde birinci basamağın verimi %80, ikinci basamağınki %50\'dir. Başlangıç maddesine göre toplam verim yüzde kaçtır?', '40', ['65', '130', '30'], 'Basamak verimleri çarpılır: 0,80 × 0,50 = 0,40, yani %40.'),
  ('CH₃COOH + C₂H₅OH → CH₃COOC₂H₅ + H₂O tepkimesinde 6 g asetik asit yeterli etanolle tepkimeye sokuluyor ve 5,28 g etil asetat elde ediliyor. Yüzde verim kaçtır? (CH₃COOH = 60, CH₃COOC₂H₅ = 88 g/mol)', '60', ['88', '40', '52,8'], '6 g asetik asit 0,1 mol\'dür; kuramsal olarak 0,1 × 88 = 8,8 g ester oluşmalıdır. Verim 5,28 / 8,8 × 100 = %60.'),
  ('Bir bakır cevheri kütlece %2 Cu₂S içermektedir. Bu cevherin 1 tonundan en çok kaç kilogram bakır elde edilebilir? (Cu = 64, S = 32)', '16', ['20', '32', '12,8'], '1 tonda 20 kg Cu₂S vardır. Cu₂S\'nin 160 kütle biriminden 128\'i bakırdır: 20 × 128/160 = 16 kg.'),
  ('Kireç üretiminde CaCO₃ → CaO + CO₂ tepkimesi kullanılıyor. İstenen ürün CaO ise bu işlemin atom ekonomisi yüzde kaçtır? (CaCO₃ = 100, CaO = 56 g/mol)', '56', ['44', '100', '78'], 'Atom ekonomisi = istenen ürünün mol kütlesi / girenlerin toplam mol kütlesi × 100 = 56 / 100 × 100 = %56. Kalan %44 CO₂ olarak çıkar.'),
  ('2A → B tepkimesinde 0,5 mol A kullanılarak 0,2 mol B elde ediliyor. Tepkimenin yüzde verimi kaçtır?', '80', ['40', '50', '100'], '0,5 mol A\'dan kuramsal olarak 0,25 mol B oluşmalıdır. Verim 0,2 / 0,25 × 100 = %80.'),
  ('Sülfürik asit üretiminde S → SO₂ → SO₃ → H₂SO₄ basamakları izlenir ve her basamakta kükürt atomları korunur. 16 g kükürtten en çok kaç gram H₂SO₄ elde edilebilir? (S = 32, H = 1, O = 16)', '49', ['16', '98', '24,5'], 'Her H₂SO₄\'te bir S atomu vardır; 16 g S = 0,5 mol en çok 0,5 mol H₂SO₄ verir. 0,5 × 98 = 49 g.'),
  ('CaCO₃ → CaO + CO₂ ve ardından CaO + H₂O → Ca(OH)₂ tepkimeleriyle sönmüş kireç üretiliyor. 50 g CaCO₃\'ten en çok kaç gram Ca(OH)₂ elde edilir? (Ca = 40, C = 12, O = 16, H = 1)', '37', ['28', '50', '74'], '50 g CaCO₃ = 0,5 mol, 0,5 mol CaO ve sonra 0,5 mol Ca(OH)₂ verir. 0,5 × 74 = 37 g.'),
  ('CO ve N₂ gazlarından oluşan, bileşimi bilinmeyen 14 g\'lık bir karışımda toplam kaç mol gaz vardır? (C = 12, N = 14, O = 16)', '0,5', ['0,25', '1,0', 'Bileşim bilinmeden bulunamaz.'], 'İki gazın da mol kütlesi 28 g/mol\'dür. Oranları ne olursa olsun 14 g karışım 14 / 28 = 0,5 mol\'dür.'),
  ('6,4 g bakır önce oksijenle CuO\'ya, ardından sülfürik asitle CuSO₄\'e dönüştürülüyor ve çözeltiden CuSO₄·5H₂O kristallendiriliyor. Kayıp olmazsa kaç gram kristal elde edilir? (Cu = 64, CuSO₄·5H₂O = 250 g/mol)', '25', ['16', '6,4', '12,5'], '6,4 g Cu = 0,1 mol\'dür; bakır atomları korunduğundan 0,1 mol CuSO₄·5H₂O = 25 g oluşur.'),
  ('Eski karbür lambalarında CaC₂ + 2H₂O → C₂H₂ + Ca(OH)₂ tepkimesiyle asetilen üretilirdi. 6,4 g kalsiyum karbürden normal koşullarda kaç litre asetilen elde edilir? (Ca = 40, C = 12)', '2,24', ['1,12', '4,48', '22,4'], 'CaC₂\'nin mol kütlesi 64 g/mol\'dür; 6,4 g = 0,1 mol, 0,1 mol C₂H₂ verir. 0,1 × 22,4 = 2,24 L.'),
  ('Bir çözeltideki sülfat iyonları, BaCl₂ eklenerek BaSO₄ hâlinde tamamen çöktürülüyor; süzülüp kurutulan çökelek 2,33 g geliyor. Çözeltide kaç mol sülfat iyonu vardı? (BaSO₄ = 233 g/mol)', '0,01', ['0,02', '0,10', '0,233'], '2,33 / 233 = 0,01 mol BaSO₄ oluşmuştur. Her formül biriminde bir SO₄²⁻ bulunduğundan sülfat 0,01 mol\'dür.'),
  ('Gravimetrik analizde aranan iyonu çöktürmek için kullanılan çöktürücü çözeltinin, hesaplanandan biraz fazla eklenmesinin amacı nedir?', 'İyonun tamamının çökmesini sağlamak', ['Çökeleğin mol kütlesini artırmak', 'Çökeleğin rengini daha belirgin hâle getirerek görünür kılmak', 'Çözeltinin hacmini sabit tutmak'], 'Çöktürücü eksik kalırsa aranan iyonun bir kısmı çözeltide kalır ve sonuç düşük çıkar. Hafif fazlası bu kaybı önler.'),
  ('Bir su örneğindeki klorür iyonları gümüş nitratla AgCl olarak çöktürülüyor ve 0,287 g çökelek elde ediliyor. Örnekte kaç miligram klorür vardır? (AgCl = 143,5 g/mol, Cl = 35,5)', '71', ['35,5', '142', '287'], '0,287 / 143,5 = 0,002 mol AgCl; içindeki Cl⁻ 0,002 × 35,5 = 0,071 g = 71 mg\'dır.'),
  ('500 mg parasetamol (C₈H₉NO₂, 151 g/mol) içeren bir tablette yaklaşık kaç milimol etken madde bulunur?', '3,3', ['0,33', '33', '1,5'], '500 mg / 151 mg/mmol ≈ 3,3 mmol. Milimol hesabında mg ile g/mol değeri doğrudan oranlanabilir.'),
  ('1 mikromol (1 µmol) maddede yaklaşık kaç tanecik bulunur? (NA = 6,02×10²³ mol⁻¹)', '6,02×10¹⁷', ['6,02×10²⁰', '6,02×10²⁹', '6,02×10¹¹'], '1 µmol = 10⁻⁶ mol\'dür; 10⁻⁶ × 6,02×10²³ = 6,02×10¹⁷ tanecik.'),
  ('Kapalı bir kapta 6 tane H₂ molekülü ile 4 tane O₂ molekülü 2H₂ + O₂ → 2H₂O tepkimesine göre tam verimle tepkimeye giriyor. Tepkime sonunda kapta hangi tanecikler bulunur?', '6 H₂O ve 1 O₂ molekülü', ['4 H₂O ve 2 H₂ molekülü', '6 H₂O ve 2 O₂ molekülü kalır, H₂ tükenir', '8 H₂O molekülü'], '6 H₂ molekülü 3 O₂ harcayarak 6 H₂O oluşturur; 4 − 3 = 1 O₂ molekülü artar.'),
  ('Bir tanecik modelinde tepkime öncesinde 4 N₂ ve 9 H₂ molekülü vardır. N₂ + 3H₂ → 2NH₃ tepkimesi tam verimle gerçekleşince toplam molekül sayısı kaç olur?', '7', ['13', '6', '5'], '9 H₂, 3 N₂ harcayarak 6 NH₃ oluşturur; 1 N₂ artar. Son durumda 6 + 1 = 7 molekül vardır.'),
  ('Bir aspirin tableti 0,36 g asetilsalisilik asit (C₉H₈O₄, 180 g/mol) içerir. Tablette yaklaşık kaç asetilsalisilik asit molekülü vardır? (NA = 6,0×10²³)', '1,2×10²¹', ['2,0×10⁻³', '6,0×10²³', '3,6×10²²'], '0,36 / 180 = 2,0×10⁻³ mol; 2,0×10⁻³ × 6,0×10²³ = 1,2×10²¹ molekül.'),
  ('Bir beslenme önerisinde günlük 2,3 g sodyum sınırı veriliyor. Sodyumun tamamı sofra tuzundan (NaCl) geliyorsa bu kaç gram tuza karşılık gelir? (Na = 23, Cl = 35,5)', '5,85', ['2,30', '3,55', '11,70'], '2,3 g Na = 0,1 mol\'dür; 0,1 mol NaCl = 0,1 × 58,5 = 5,85 g tuz.'),
  ('Kâğıda çekilen bir kurşun kalem çizgisinde 1,2 mg grafit (saf karbon) bulunduğu varsayılıyor. Çizgide yaklaşık kaç karbon atomu vardır? (C = 12, NA = 6,0×10²³)', '6,0×10¹⁹', ['6,0×10²²', '1,0×10⁻⁴', '7,2×10²⁰'], '1,2 mg = 1,2×10⁻³ g; 1,2×10⁻³ / 12 = 1,0×10⁻⁴ mol. 1,0×10⁻⁴ × 6,0×10²³ = 6,0×10¹⁹ atom.'),
  ('Bir küp şeker yaklaşık 3,42 g sakkarozdan (C₁₂H₂₂O₁₁, 342 g/mol) oluşur. Bu küp şekerde kaç mol oksijen atomu vardır?', '0,11', ['0,01', '0,22', '0,011'], '3,42 / 342 = 0,01 mol sakkaroz; her molekülde 11 O atomu bulunduğundan 0,11 mol O atomu vardır.'),
  ('Bir öğrenci "1 mol su ile 1 mol demir aynı koşullarda aynı hacmi kaplar." diyor. Bu iddia için en doğru değerlendirme hangisidir?', 'Yanlıştır; katı ve sıvıların molar hacimleri maddeye göre değişir.', ['Doğrudur; 1 mol her maddede 22,4 L hacim kaplar.', 'Doğrudur; tanecik sayıları eşit olan maddelerin hacimleri de eşittir.', 'Yanlıştır; çünkü demirin 1 molünde daha az tanecik vardır.'], 'Tanecik sayıları eşit olsa da katı ve sıvılarda hacim, taneciklerin boyutuna ve dizilişine bağlıdır (1 mol su ≈ 18 mL, 1 mol demir ≈ 7 mL).'),
  ('Açık bir kapta gerçekleştirilen bir tepkimenin sonunda ölçülen kütle, girenlerin toplam kütlesinden az çıkıyor. En olası açıklama hangisidir?', 'Gaz hâlindeki bir ürün kaptan kaçmıştır.', ['Tepkimede kütle yok olmuştur.', 'Ürünlerin mol kütlesi girenlerinkinden küçüktür.', 'Tepkime sırasında atomlar parçalanmıştır.'], 'Kütle korunur; açık kapta oluşan CO₂ gibi gazlar ortamdan uzaklaşınca terazi daha az kütle gösterir. Kapalı kapta aynı tepkime kütle kaybı göstermez.'),
  ('Bir öğrenci 9 g suyun mol sayısını 9 × 18 = 162 mol olarak hesaplıyor. Öğrencinin hatası nedir?', 'Kütleyi mol kütlesiyle çarpmış; bölmeliydi.', ['Suyun mol kütlesini yanlış almış; 16 olmalıydı.', 'Avogadro sayısıyla çarpmayı unutmuş.', 'Hesap doğrudur; yalnızca birim yanlış yazılmıştır.'], 'n = m / M olduğundan 9 / 18 = 0,5 mol olmalıdır. Birim kontrolü de hatayı gösterir: g × g/mol mol vermez.'),
  ('Her biri yaklaşık 1 mg kütleli 6×10²³ kum tanesinin toplam kütlesi yaklaşık kaç kilogram olur?', '6×10¹⁷', ['6×10²⁰', '6×10¹⁴', '6×10²³'], '6×10²³ × 1 mg = 6×10²³ mg = 6×10²⁰ g = 6×10¹⁷ kg. Bu, büyük bir dağın kütlesi düzeyindedir ve Avogadro sayısının büyüklüğünü gösterir.'),
  ('Aşağıdaki örneklerden hangisinin kütlesi 1 mol ozonun (O₃) kütlesine eşittir? (O = 16)', '1,5 mol O₂', ['1 mol O₂', '2 mol O₂', '0,75 mol O₂'], '1 mol O₃ = 48 g\'dır. 1,5 mol O₂ = 1,5 × 32 = 48 g; ikisi de 3 mol O atomu içerir.'),
  ('1 mol Fe³⁺ iyonunun taşıdığı toplam yük yaklaşık kaç coulomb\'dur? (1 mol elektronun yükü ≈ 96 500 C)', '289 500', ['96 500', '193 000', '32 167'], 'Her Fe³⁺ iyonu 3 birim artı yük taşır. 1 mol iyonun yükü 3 × 96 500 = 289 500 C\'tur.'),
  ('Zn + Cu²⁺ → Zn²⁺ + Cu tepkimesinde 0,2 mol çinko tamamen yükseltgendiğinde kaç gram bakır indirgenip açığa çıkar? (Cu = 64)', '12,8', ['6,4', '25,6', '13,0'], 'Çinko 2 elektron verir, Cu²⁺ 2 elektron alır; mol oranı 1 : 1\'dir. 0,2 mol Cu × 64 = 12,8 g.'),
  ('Hidrojen yakıtlı bir araçta 1 kg H₂ tamamen yandığında kaç kilogram su oluşur? (H = 1, O = 16)', '9', ['1', '8', '18'], '2H₂ + O₂ → 2H₂O; 2 g H₂\'den 18 g su oluşur, yani kütle 9 katına çıkar. 1 kg H₂\'den 9 kg su oluşur.'),
  ('Kabartma tozu sirkeyle NaHCO₃ + CH₃COOH → CH₃COONa + H₂O + CO₂ tepkimesini verir. 8,4 g NaHCO₃ yeterli sirkeyle tepkimeye girdiğinde kaç gram CO₂ oluşur? (Na = 23, H = 1, C = 12, O = 16)', '4,4', ['8,4', '2,2', '44,0'], 'NaHCO₃ 84 g/mol\'dür; 8,4 g = 0,1 mol ve 0,1 mol CO₂ = 4,4 g oluşur.'),
  ('Bir gaz örneği kireç suyundan geçirildiğinde Ca(OH)₂ + CO₂ → CaCO₃ + H₂O tepkimesiyle 1,0 g CaCO₃ çöküyor. Örnekte kaç miligram CO₂ vardı? (CaCO₃ = 100, CO₂ = 44 g/mol)', '440', ['100', '1000', '220'], '1,0 g CaCO₃ = 0,01 mol\'dür; aynı mol sayıda CO₂ gerekir: 0,01 × 44 = 0,44 g = 440 mg.'),
  ('Bir ağacın bir yılda fotosentezle 22 kg CO₂ bağladığı varsayılıyor. Bu CO₂\'deki karbonun tamamı ağacın yapısına geçerse ağaç kaç kilogram karbon kazanmış olur? (C = 12, O = 16)', '6', ['12', '22', '3'], 'CO₂\'nin 44 kütle biriminden 12\'si karbondur. 22 × 12/44 = 6 kg karbon.'),
  ('Hücresel solunumda C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O tepkimesi gerçekleşir. 180 g glukoz tamamen yükseltgendiğinde kaç gram CO₂ oluşur? (C = 12, H = 1, O = 16)', '264', ['44', '1080', '132'], '180 g glukoz 1 mol\'dür ve 6 mol CO₂ verir: 6 × 44 = 264 g.'),
  ('Aşağıdaki örneklerden hangisi en fazla sayıda molekül içerir? (H = 1, C = 12, O = 16)', '18 g H₂O', ['1 g H₂', '16 g O₂', '8,8 g CO₂'], 'Mol sayıları: H₂O 1 mol; H₂, O₂ ve CO₂ ise 0,5\'er mol\'dür. En çok molekül 18 g suda bulunur.'),
  ('Avogadro sayısı bilindiğine göre, saf bir maddenin mol sayısını başka bir veri gerekmeden hesaplamaya aşağıdakilerden hangisi tek başına yeter?', 'Tanecik sayısı', ['Örneğin kütlesi', 'Örneğin hacmi', 'Örneğin yoğunluğu'], 'n = N / NA olduğundan tanecik sayısı tek başına yeterlidir. Kütleden mol bulmak için mol kütlesi, hacimden bulmak için yoğunluk ve mol kütlesi de gerekir.'),
  ('Toplam x tane atom içeren bir propan (C₃H₈) örneğinde kaç tane propan molekülü vardır?', 'x/11', ['11x', 'x/3', '8x/11'], 'Her C₃H₈ molekülü 3 + 8 = 11 atom içerir; bu nedenle molekül sayısı x/11\'dir.'),
  ('Bir kaptaki amonyak (NH₃) örneğinde 1,2 mol hidrojen atomu bulunmaktadır. Örnekte toplam kaç mol atom vardır?', '1,6', ['0,4', '1,2', '4,8'], '1,2 mol H, 0,4 mol NH₃\'e karşılık gelir. 0,4 mol NH₃\'te 0,4 × 4 = 1,6 mol atom vardır.'),
  ('Kaç mol CO₂, 1 mol glukozun (C₆H₁₂O₆) içerdiği kadar oksijen atomu içerir?', '3', ['6', '2', '12'], '1 mol glukozda 6 mol O atomu vardır. Her CO₂\'de 2 O bulunduğundan 6 / 2 = 3 mol CO₂ gerekir.'),
  ('Eşit sayıda molekül içeren SO₂ ve SO₃ örneklerindeki oksijen atomu sayıları oranı (SO₂ / SO₃) kaçtır?', '2/3', ['3/2', '1', '4/5'], 'Molekül sayıları eşitse oksijen atomları molekül başına oksijen sayısıyla orantılıdır: 2/3.'),
  ('Fe₂(SO₄)₃ formülüne sahip bir formül biriminde kaç farklı element ve toplam kaç atom bulunur?', '3 element, 17 atom', ['3 element, 9 atom', '4 element, 17 atom', '3 element, 14 atom'], 'Demir, kükürt ve oksijen olmak üzere 3 element vardır. Atomlar: 2 Fe + 3 S + 12 O = 17.'),
  ('aA + bB → cC tepkimesinde 3 mol A ile 2 mol B artansız harcanarak 4 mol C oluşuyor. Tepkimenin en küçük tam sayılı denklemi hangisidir?', '3A + 2B → 4C', ['A + B → C', '2A + 3B → 4C', '6A + 4B → 8C'], 'Katsayılar harcanan ve oluşan mol sayılarıyla orantılıdır: 3 : 2 : 4. Bu oran zaten en küçük tam sayılardır.'),
  ('Kuyumculukta 1 karat 0,2 g\'dır. 1 karatlık saf bir elmasta yaklaşık kaç karbon atomu bulunur? (C = 12, NA = 6,0×10²³)', '1,0×10²²', ['1,2×10²³', '6,0×10²³', '2,4×10²¹'], '0,2 / 12 ≈ 0,0167 mol karbon; 0,0167 × 6,0×10²³ ≈ 1,0×10²² atom.'),
  ('1 litre saf suda yaklaşık kaç mol su molekülü bulunur? (Yoğunluk 1,0 g/mL, H₂O = 18 g/mol)', '55,6', ['18', '1,0', '1000,0'], '1 L su 1000 g\'dır. 1000 / 18 ≈ 55,6 mol su molekülü içerir.'),
  ('Kimya meraklılarınca "Mol Günü" olarak kutlanan tarih ve saat, Avogadro sayısının 6,02×10²³ yazılışına dayanır. Bu gün hangisidir?', '23 Ekim, 6.02', ['6 Şubat, 10.23', '2 Haziran, 6.23', '10 Haziran, 2.23'], 'Ay/gün sıralamasıyla 10/23 ve saat 6.02, sayının 6,02×10²³ yazılışını çağrıştırır; bu nedenle 23 Ekim\'de 6.02\'den 18.02\'ye kadar kutlanır.'),
  ('Suyun elektrolizinde 4 mol elektron geçtiğinde anotta kaç mol O₂ oluşur? (2H₂O → O₂ + 4H⁺ + 4e⁻)', '1', ['2', '4', '0,5'], 'Yarı tepkimeye göre 1 mol O₂ oluşurken 4 mol elektron verilir. 4 mol elektron 1 mol O₂\'ye karşılık gelir.'),
  ('4,0 g kalsiyum havada tamamen yandığında 2Ca + O₂ → 2CaO tepkimesine göre kaç gram kalsiyum oksit oluşur? (Ca = 40, O = 16)', '5,6', ['4,0', '2,8', '11,2'], '4,0 g Ca = 0,1 mol\'dür; 0,1 mol CaO = 0,1 × 56 = 5,6 g oluşur. Kütledeki artış bağlanan oksijenden gelir.'),
  ('1 mol karbon-12 atomu ile 1 mol karbon-14 atomunun kütleleri arasındaki fark yaklaşık kaç gramdır?', '2', ['1', '12', '14'], 'Bir ¹⁴C atomu bir ¹²C atomundan yaklaşık 2 akb ağırdır. 1 mol atom için fark 2 g olur.'),
  ('Bir iyonik bileşik olan 0,3 mol Ca₃(PO₄)₂ örneğinde kaç mol katyon bulunur?', '0,9', ['0,3', '0,6', '1,5'], 'Her formül biriminde 3 Ca²⁺ katyonu ve 2 PO₄³⁻ anyonu vardır. 0,3 × 3 = 0,9 mol katyon.'),
  ('Girenlerin denkleştirilmiş denklemdeki katsayılarla tam aynı mol oranında alındığı, tepkime sonunda hiçbir girenin artmadığı karışıma ne ad verilir?', 'Stokiyometrik karışım', ['Doymuş karışım', 'Heterojen (adi) karışım', 'Azeotrop karışım'], 'Stokiyometrik karışımda girenler tam katsayı oranında olduğundan hepsi aynı anda tükenir; sınırlayıcı ya da artan bileşen yoktur.'),
  ('Bir tepkimede sınırlayıcı bileşen tamamen tükendikten sonra kaba artan bileşenden bir miktar daha eklenirse oluşan ürün miktarı nasıl değişir?', 'Değişmez.', ['Eklenen miktarla orantılı artar.', 'Azalır.', 'İki katına çıkar.'], 'Ürün miktarını sınırlayıcı bileşen belirler; o tükendiği için artan bileşenden eklemek yeni ürün oluşturmaz.'),
  ('Stokiyometri problemlerini çözerken atılması gereken ilk adım hangisidir?', 'Denklemi denkleştirmek', ['Ürünlerin kütlesini tartmak', 'Avogadro sayısını yeniden hesaplamak', 'Tepkime hızını ölçmek'], 'Mol oranları ancak denkleştirilmiş denklemden okunabilir; denklem denk değilse sonraki bütün hesaplar yanlış olur.'),
  ('Kendiliğinden ısınan bazı yemek kutularında CaO + H₂O → Ca(OH)₂ tepkimesi kullanılır. 5,6 g CaO\'nun tamamen tepkimeye girmesi için en az kaç gram su gerekir? (Ca = 40, O = 16, H = 1)', '1,8', ['5,6', '3,6', '0,9'], '5,6 g CaO = 0,1 mol\'dür ve 0,1 mol (1,8 g) su ile tepkimeye girer.'),
  ('5,4 g alüminyum ile 21,3 g klor artansız birleşerek bir klorür oluşturuyor. Bileşiğin basit formülü hangisidir? (Al = 27, Cl = 35,5)', 'AlCl₃', ['AlCl', 'AlCl₂', 'Al₂Cl₃'], 'Al: 5,4/27 = 0,2 mol; Cl: 21,3/35,5 = 0,6 mol. Oran 1 : 3 olduğundan AlCl₃\'tür.'),
  ('Normal koşullarda 5,6 L etilen (C₂H₄) gazının kütlesi kaç gramdır? (C = 12, H = 1)', '7', ['14', '3,5', '28'], '5,6 / 22,4 = 0,25 mol; kütle 0,25 × 28 = 7 g olur.'),
  ('0,2 mol Fe₂(SO₄)₃ katısı suda tamamen çözünüp iyonlarına ayrışırsa çözeltide toplam kaç mol iyon bulunur?', '1,0', ['0,4', '0,6', '0,8'], 'Her formül birimi 2 Fe³⁺ ve 3 SO₄²⁻ olmak üzere 5 iyon verir; 0,2 × 5 = 1,0 mol iyon oluşur.'),
  ('Bir bakır oksit örneğinde 3,2 g bakır 0,8 g oksijenle birleşmiştir. Aynı bileşiğin başka bir örneğinde 12,8 g bakırla kaç gram oksijen birleşir?', '3,2', ['1,6', '6,4', '0,8'], 'Cu/O kütle oranı 3,2/0,8 = 4\'tür ve sabittir. 12,8 / 4 = 3,2 g oksijen gerekir.'),
  ('FeS ve FeS₂ bileşiklerinde 56 g demirle birleşen kükürt kütleleri oranı (FeS / FeS₂) kaçtır?', '1/2', ['1/1', '2/3', '1/4'], '56 g Fe, FeS\'te 32 g, FeS₂\'de 64 g kükürtle birleşir. Oran 32/64 = 1/2 olur.'),
  ('2KClO₃ → 2KCl + 3O₂ tepkimesiyle 0,6 mol O₂ elde etmek için en az kaç mol KClO₃ ayrışmalıdır?', '0,4', ['0,6', '0,9', '0,3'], 'Katsayı oranı KClO₃ : O₂ = 2 : 3 olduğundan 0,6 × 2/3 = 0,4 mol KClO₃ gerekir.'),
  ('0,25 kmol kalsiyum karbonat (CaCO₃, 100 g/mol) kaç kilogramdır?', '25', ['2,5', '250', '0,25'], '1 kmol = 1000 mol olduğundan 0,25 kmol = 250 mol; 250 × 100 g = 25 000 g = 25 kg\'dır.'),
  ('Eşit kütlelerde alınan berilyum (9 g/mol), magnezyum (24 g/mol) ve kalsiyum (40 g/mol) örneklerinin atom sayıları için hangi sıralama doğrudur?', 'Be > Mg > Ca', ['Ca > Mg > Be', 'Mg > Be > Ca', 'Be = Mg = Ca'], 'Kütle sabitken atom sayısı mol kütlesiyle ters orantılıdır; mol kütlesi en küçük olan Be en çok, Ca en az atom içerir.'),
  ('Bir bitki fotosentezde 88 g karbondioksit bağlıyor. 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂ tepkimesine göre bu sırada kaç gram oksijen açığa çıkar? (C = 12, O = 16)', '64', ['32', '88', '128'], '88 / 44 = 2 mol CO₂ bağlanır ve katsayılar eşit olduğundan 2 mol O₂ oluşur. Kütle 2 × 32 = 64 g\'dır.'),
  ('Sönmemiş kireç CaO suyla CaO + H₂O → Ca(OH)₂ tepkimesine girer. 14 g CaO ile en çok kaç gram sönmüş kireç oluşur? (Ca = 40, O = 16, H = 1)', '18,5', ['37', '14', '9,25'], '14 / 56 = 0,25 mol CaO, 0,25 mol Ca(OH)₂ verir. Kütle 0,25 × 74 = 18,5 g\'dır.'),
  ('Tepkime kabında 4 CO ve 3 O₂ molekülü vardır. 2CO + O₂ → 2CO₂ tepkimesi tam verimle gerçekleşirse sonunda kapta toplam kaç molekül bulunur?', '5', ['4', '6', '7'], '4 CO, 2 O₂ ile birleşip 4 CO₂ oluşturur ve 1 O₂ artar. Sonuçta 4 CO₂ + 1 O₂ = 5 molekül vardır.'),
  ('Bir tablette 0,325 g aspirin (C₉H₈O₄, 180 g/mol) bulunmaktadır. Tablet kaç milimol aspirin içerir?', '1,8', ['0,18', '18', '3,25'], 'n = 0,325 g / 180 g/mol ≈ 1,8 × 10⁻³ mol = 1,8 mmol.'),
  ('Bir bardak sütte yaklaşık 300 mg kalsiyum (Ca = 40 g/mol) bulunur. Bu miktar kaç milimol kalsiyuma karşılık gelir?', '7,5', ['0,75', '12', '75'], '300 mg = 0,300 g; n = 0,300 / 40 = 7,5 × 10⁻³ mol = 7,5 mmol\'dür.'),
  ('25 g mavi taş (CuSO₄·5H₂O, 250 g/mol) tamamen susuzlaştırılıyor. Kütle kaybı kaç gramdır? (H₂O = 18 g/mol)', '9', ['16', '25', '4,5'], '25 / 250 = 0,1 mol hidrat 0,5 mol su içerir. Su kütlesi 0,5 × 18 = 9 g\'dır; kütle kaybı budur.'),
  ('PCl₃ ve PCl₅ bileşiklerinde sabit kütledeki fosforla birleşen klor kütleleri oranı (PCl₃ / PCl₅) kaçtır? (P = 31, Cl = 35,5)', '3/5', ['2/3', '3/2', '11/20'], '31 g fosfor PCl₃\'te 3 × 35,5 g, PCl₅\'te 5 × 35,5 g klorla birleşir. Oran 3/5\'tir; katlı oranlar yasasına uygun küçük tam sayılar çıkar.'),
  ('Kapalı bir kapta 6,8 g H₂O₂ tamamen ayrışarak 3,6 g su ve bir miktar oksijen gazı veriyor. Kütlenin korunumuna göre oluşan oksijenin kütlesi kaç gramdır?', '3,2', ['10,4', '1,6', '6,4'], 'Toplam kütle korunur: 6,8 = 3,6 + m(O₂), buradan m(O₂) = 3,2 g bulunur. Bu değer 0,1 mol O₂ ile de uyumludur.'),
  ('Eşdeğer kütlesi 20 g/eş olan ve bileşiklerinde +2 değerlik gösteren bir metalin mol kütlesi kaç g/mol\'dür?', '40', ['10', '20', '36,5'], 'Eşdeğer kütle = mol kütlesi / değerlik olduğundan mol kütlesi 20 × 2 = 40 g/mol bulunur.'),
  ('NH₄NO₃ → N₂O + H₂O tepkimesi denkleştirildiğinde su için hangi katsayı bulunur?', '2', ['1', '3', '4'], 'NH₄NO₃ → N₂O + 2H₂O biçiminde denkleşir. Sol tarafta 4 H ve 3 O olduğundan sağda 2 H₂O yazılır.'),
  ('Ga\'nın doğal izotopları ⁶⁹Ga (%60) ve ⁷¹Ga (%40) olarak alınırsa kütle spektrumundan hesaplanan ortalama atom kütlesi kaç olur?', '69,8', ['70,05', '69,2', '70,4'], '0,60 × 69 + 0,40 × 71 = 41,4 + 28,4 = 69,8 bulunur.'),
  ('6,02 × 10²¹ tane su molekülü kaç milimol su demektir? (NA = 6,02 × 10²³ mol⁻¹)', '10', ['1', '100', '0,1'], '6,02 × 10²¹ / 6,02 × 10²³ = 0,01 mol = 10 mmol\'dür.'),
  ('0,5 mol ¹⁴C atomunda toplam kaç mol nötron bulunur? (Karbonun atom numarası 6\'dır.)', '4', ['3', '7', '1,5'], '¹⁴C\'nin nötron sayısı 14 − 6 = 8\'dir. 0,5 × 8 = 4 mol nötron bulunur.'),
  ('0,5 mol CaCl₂ katısında toplam kaç tane Cl⁻ iyonu bulunur? (Avogadro sabiti: 6,022 × 10²³ mol⁻¹)', '6,02 × 10²³', ['3,01 × 10²³', '1,806 × 10²⁴', '1,2 × 10²³'], 'Her formül biriminde 2 Cl⁻ vardır; 0,5 × 2 = 1 mol Cl⁻ iyonu bulunur. Bu da NA = 6,02 × 10²³ tanedir.'),
  ('Mavi taşta, CuSO₄·5H₂O, bakırın kütlece yüzdesi kaçtır? (Cu = 64, S = 32, O = 16, H = 1)', '25,6', ['0,256', '64,0', '12,8'], 'Mol kütlesi 250 g/mol\'dür ve 1 mol hidratta 64 g bakır vardır. 64 / 250 × 100 = %25,6.'),
  ('0,5 mol asetilen (C₂H₂) gazı 2C₂H₂ + 5O₂ → 4CO₂ + 2H₂O tepkimesiyle tamamen yanıyor. Harcanan oksijen kaç moldür?', '1,25', ['0,5', '0,625', '2,5'], 'O₂ : C₂H₂ katsayı oranı 5 : 2\'dir. 0,5 × 5/2 = 1,25 mol O₂ harcanır.'),
  ('BaCl₂ ile H₂SO₄ arasındaki çökelme tepkimesi en küçük tam sayılarla denkleştirildiğinde katsayıların toplamı kaç olur?', '5', ['4', '6', '7 veya 8'], 'BaCl₂ + H₂SO₄ → BaSO₄ + 2HCl; katsayılar toplamı 1 + 1 + 1 + 2 = 5\'tir.'),
  ('N₂ + 3H₂ → 2NH₃ tepkimesi sırasında aşağıdakilerden hangisi değişir?', 'Sistemdeki toplam mol (molekül) sayısı', ['Toplam kütle ile her elementin toplam atom sayısı', 'Azot atomlarının toplam sayısı', 'Hidrojen atomlarının toplam sayısı'], 'Girenlerde 4 mol, ürünlerde 2 mol gaz vardır; mol ve molekül sayısı korunmaz. Kütle ve her elementin atom sayısı ise tepkimede korunur.'),
  ('Açık havada yakılan 2,4 g magnezyum şerit 2Mg + O₂ → 2MgO tepkimesine göre tamamen yanıyor. Yanma sonrası katı kalıntının kütlesi kaç gramdır? (Mg = 24, O = 16)', '4,0', ['2,4', '1,6', '6,40'], '2,4 / 24 = 0,1 mol Mg 0,1 mol MgO verir. Kütle 0,1 × 40 = 4,0 g\'dır; artış havadan katılan 1,6 g oksijenden gelir.'),
  ('Saf kalsiyum karbonat kuvvetle ısıtılarak CaCO₃ → CaO + CO₂ tepkimesiyle tamamen ayrıştırılırsa kütlesi yüzde kaç azalır? (Ca = 40, C = 12, O = 16)', '44', ['56', '22', '100'], '1 mol CaCO₃ (100 g) 1 mol CO₂ (44 g) kaybeder; kütle kaybı 44 / 100 × 100 = %44\'tür.'),
  ('Bir ATP molekülünün mol kütlesi yaklaşık 507 g/mol\'dür. 0,2 mmol ATP kaç miligramdır?', '101,4', ['10,140', '1014', '2535'], '0,2 mmol = 2 × 10⁻⁴ mol; kütle 2 × 10⁻⁴ × 507 = 0,1014 g = 101,4 mg\'dır.'),
  ('Asidik ortamda Cr₂O₇²⁻ + 6Fe²⁺ + 14H⁺ → 2Cr³⁺ + 6Fe³⁺ + 7H₂O tepkimesine göre 0,1 mol Cr₂O₇²⁻ kaç mol Fe²⁺ iyonunu yükseltger?', '0,6', ['0,10', '0,3', '1,4'], 'Cr₂O₇²⁻ : Fe²⁺ katsayı oranı 1 : 6\'dır. 0,1 × 6 = 0,6 mol Fe²⁺ yükseltgenir.'),
  ('IO₃⁻ + 5I⁻ + 6H⁺ → 3I₂ + 3H₂O tepkimesinde 0,1 mol IO₃⁻ yeterli I⁻ ve H⁺ ile tepkimeye girerse kaç mol I₂ oluşur?', '0,3', ['0,10', '0,5', '0,6'], 'Katsayı oranı IO₃⁻ : I₂ = 1 : 3\'tür. 0,1 × 3 = 0,3 mol I₂ oluşur.'),
  ('Bir tankerde 18 ton su (H₂O = 18 g/mol) taşınıyor. Bu miktar kaç kilomol (kmol) sudur?', '1000', ['1', '18', '1 000 000'], '18 ton = 18 000 kg; 1 kmol su 18 kg olduğundan 18 000 / 18 = 1000 kmol\'dür.'),
  ('Bir amonyak sentezinde 6 mol H₂ yeterli N₂ ile tepkimeye giriyor ve kuramsal olarak 4 mol NH₃ beklenirken 3,2 mol NH₃ elde ediliyor. Verim yüzde kaçtır?', '80', ['53,0', '64', '75'], 'N₂ + 3H₂ → 2NH₃\'e göre 6 mol H₂ en çok 4 mol NH₃ verir. Yüzde verim 3,2 / 4 × 100 = %80\'dir.'),
  ('Eşit kütlelerde alınan A ve B elementlerinden A\'nın atom kütlesi B\'ninkinin 2 katıdır. Bu iki örnekteki atom sayıları için ne söylenebilir?', 'A örneğinde B örneğine göre yarı sayıda atom vardır.', ['A örneğinde B örneğine göre iki kat atom vardır.', 'İki örnekte eşit sayıda atom vardır.', 'A örneğindeki atom sayısı B\'ninkinin dört katıdır.'], 'Kütle sabitken atom sayısı atom kütlesiyle ters orantılıdır. A\'nın atom kütlesi iki kat olduğundan atom sayısı yarıya düşer.'),
  ('Aynı mol sayısında (0,1 mol) Na, Mg ve Al metalleri fazla asitle tepkimeye giriyor. En çok H₂ hangisinden açığa çıkar? (Metaller sırasıyla +1, +2, +3 değerlik gösterir.)', 'Al', ['Na', 'Mg', 'Üçünden de eşit miktarda'], 'Açığa çıkan H₂ mol sayısı verilen elektron sayısının yarısıdır: Na 0,05; Mg 0,10; Al 0,15 mol. En çok Al verir.'),
  ('Bir sentezde pahalı bir girenin tamamen tüketilmesi için ucuz olan giren çoğunlukla fazla alınır. Bu uygulamada fazla alınan madde için ne söylenebilir?', 'Sınırlayıcı değildir ve tepkime sonunda artar.', ['Sınırlayıcı bileşendir ve ürün miktarını belirler.', 'Kuramsal verimi artırarak ürün kütlesini yükseltir.', 'Katalizör gibi davranır ve tepkimede harcanmaz.'], 'Fazla alınan giren sınırlayıcı değildir; ürün miktarı pahalı girenin mol sayısıyla belirlenir. Fazlalık tepkime sonunda artık olarak kalır.'),
  ('1 mol buz ile 1 mol sıvı su karşılaştırıldığında hangisi doğrudur?', 'Kütleleri ve molekül sayıları eşittir, hacimleri farklıdır.', ['Molekül sayıları eşit, kütleleri farklıdır.', 'Kütleleri eşit, molekül sayıları farklıdır.', 'Hacimleri eşit, kütleleri farklıdır.'], 'Her iki örnek de 18 g ve NA tane H₂O molekülü içerir. Buzun yoğunluğu daha küçük olduğundan hacmi daha büyüktür.'),
  ('1 mol elmas ile 1 mol grafit karşılaştırıldığında aşağıdakilerden hangisi doğrudur? (C = 12)', 'Atom sayıları ve kütleleri eşittir, yoğunlukları farklıdır.', ['Elmasın kütlesi grafitten büyüktür.', 'Grafitte elmastan daha çok atom bulunur.', 'Her ikisi de aynı yoğunluğa sahiptir.'], 'İkisi de saf karbondur; 1 mol, 12 g ve NA atom demektir. Kristal yapıları farklı olduğundan yoğunlukları farklıdır.'),
  ('1 mol He gazı ile 1 mol H₂ gazındaki atom sayıları için hangisi doğrudur?', 'H₂ örneğinde He örneğinin iki katı atom vardır.', ['He örneğinde H₂ örneğinin iki katı atom vardır.', 'İki örnekte de eşit sayıda atom vardır.', 'He örneğinde H₂ örneğinin dört katı atom vardır.'], 'Helyum tek atomlu olduğundan 1 mol He, NA atom içerir. H₂ iki atomlu olduğundan 1 mol H₂, 2NA atom içerir.'),
  ('5,3 g Na₂CO₃ fazla HCl ile Na₂CO₃ + 2HCl → 2NaCl + H₂O + CO₂ tepkimesine göre tepkimeye giriyor. Normal koşullarda kaç litre CO₂ açığa çıkar? (Na = 23, C = 12, O = 16)', '1,12', ['2,240', '0,56', '11,2'], '5,3 / 106 = 0,05 mol Na₂CO₃ 0,05 mol CO₂ verir. Hacim 0,05 × 22,4 = 1,12 L\'dir.'),
  ('9,8 g bakır(II) hidroksit ısıtıldığında Cu(OH)₂ → CuO + H₂O tepkimesiyle tamamen ayrışıyor. Geriye kalan siyah CuO kaç gramdır? (Cu = 64, O = 16, H = 1)', '8,0', ['1,80', '9,8', '4,0'], '9,8 / 98 = 0,1 mol Cu(OH)₂ 0,1 mol CuO verir. Kütle 0,1 × 80 = 8,0 g\'dır; 1,8 g su buharlaşır.'),
  ('Çinko sülfür cevheri kavrulurken 2ZnS + 3O₂ → 2ZnO + 2SO₂ tepkimesi gerçekleşir. 97 g ZnS tamamen kavrulursa kaç gram ZnO elde edilir? (Zn = 65, S = 32, O = 16)', '81', ['97', '40,5', '162'], '97 / 97 = 1 mol ZnS 1 mol ZnO verir. Kütle 81 g\'dır.'),
  ('Bir X atomunun kütlesi bir Y atomunun kütlesinin 3 katıdır. 6 g X ile aynı sayıda atom içeren Y örneği kaç gramdır?', '2', ['18', '1', '12'], 'Eşit atom sayısı eşit mol demektir; kütleler atom kütleleriyle orantılıdır. Y\'nin kütlesi 6 / 3 = 2 g\'dır.'),
  ('Doğal bakır atomlarının yaklaşık %69\'u ⁶³Cu izotopudur. 1 mol doğal bakır atomunda yaklaşık kaç mol ⁶³Cu bulunur?', '0,69', ['0,310', '0,63', '1,0'], 'Bolluk yüzdesi atom sayısı oranıdır. 1 mol doğal bakırın %69\'u, yani 0,69 mol atomu ⁶³Cu\'dur.'),
  ('500 mg\'lık bir C vitamini (askorbik asit, C₆H₈O₆, 176 g/mol) tabletinde yaklaşık kaç milimol askorbik asit bulunur?', '2,84', ['0,284', '28,4', '88,0'], '0,500 g / 176 g/mol ≈ 2,84 × 10⁻³ mol = 2,84 mmol\'dür.'),
  ('Siyah-beyaz fotoğraf filminde ışığa duyarlı madde AgBr\'dür (188 g/mol). 0,188 g AgBr içindeki gümüşün kütlesi kaç gramdır? (Ag = 108)', '0,108', ['0,0800', '0,188', '1,08'], '0,188 / 188 = 0,001 mol AgBr ve 0,001 mol Ag vardır. Kütle 0,001 × 108 = 0,108 g\'dır.'),
  ('Titanyum, Kroll yönteminde TiCl₄ + 2Mg → Ti + 2MgCl₂ tepkimesiyle elde edilir. 19 g TiCl₄ (190 g/mol) tam verimle tepkimeye girerse kaç gram Ti oluşur? (Ti = 48)', '4,8', ['9,60', '2,4', '19'], '19 / 190 = 0,1 mol TiCl₄ 0,1 mol Ti verir. Kütle 0,1 × 48 = 4,8 g\'dır.'),
  ('0,37 g Ca(OH)₂ (74 g/mol), fazla CO₂ ile Ca(OH)₂ + CO₂ → CaCO₃ + H₂O tepkimesine göre tamamen çöktürülüyor. Oluşan CaCO₃ kaç miligramdır? (Ca = 40, C = 12, O = 16)', '500', ['370,0', '50', '740'], '0,37 / 74 = 0,005 mol Ca(OH)₂ 0,005 mol CaCO₃ verir. Kütle 0,005 × 100 = 0,5 g = 500 mg\'dır.'),
  ('Klor-alkali sürecinde 2NaCl + 2H₂O → 2NaOH + H₂ + Cl₂ tepkimesi gerçekleşiyor. 11,7 g NaCl tamamen dönüşürse kaç gram NaOH oluşur? (Na = 23, Cl = 35,5, O = 16, H = 1)', '8,0', ['4,0', '11,7', '16,0'], '11,7 / 58,5 = 0,2 mol NaCl ve katsayılar eşit olduğundan 0,2 mol NaOH oluşur. Kütle 0,2 × 40 = 8,0 g\'dır.'),
  ('Endüstriyel üre sentezinde 2NH₃ + CO₂ → CO(NH₂)₂ + H₂O tepkimesi kullanılır. 34 g NH₃ ve yeterli CO₂ ile tam verimle kaç gram üre (60 g/mol) elde edilir? (N = 14, H = 1)', '60', ['30', '120', '34'], '34 / 17 = 2 mol NH₃ 1 mol üre verir. Kütle 1 × 60 = 60 g\'dır.'),
];
